mapper.select:
select ti.id, ti.code, ti.source_type as sourceType, ti.source_code as sourceCode, ti.transfer_direction as transferDirection, ti.approve_status as approveStatus, ti.invalid_status as invalidStatus, ti.batch_no, tid.id as detailId, tid.sku_id as skuId, tid.sku_no as skuNo, ti.bill_date as billDate, tid.qty, tid.unit, tid.in_warehouse_id as inWarehouseId, tid.in_warehouse_name as inWarehouseName, tid.out_warehouse_id as outWarehouseId, tid.out_warehouse_name as outWarehouseName, tid.remark, ti.approve_user_name as approveUserName, ti.create_user_name as createUserName, ti.create_time as createTime, tid.in_warehouse_location as inWarehouseLocation, tid.out_warehouse_location as outWarehouseLocation from transfer_info ti inner join transfer_info_detail tid on ti.id = tid.main_id and tid.is_deleted = false
${params.sqlMap.default} and ti.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ti.id desc,tid.id asc

select
count(distinct ti.id)
from transfer_info ti
left join transfer_info_detail tid on ti.id = tid.main_id and tid.is_deleted = false

    ti.is_deleted = false

        and ti.approve_status in

            #{item}



        and ti.invalid_status = #{params.invalidStatus}


        and ti.bill_date >= #{params.billDateList[0]} and  (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ti.bill_date


        ${params.permissionSql}

select ti.id, ti.code, ti.source_type as sourceType, ti.source_code as sourceCode, ti.transfer_direction as transferDirection, ti.approve_status as approveStatus, ti.invalid_status as invalidStatus, tid.sku_id as skuId, tid.sku_no as skuNo, ti.bill_date as billDate, tid.qty, tid.unit, tid.in_warehouse_name as inWarehouseName, tid.out_warehouse_name as outWarehouseName, tid.remark, ti.approve_user_name as approveUserName, ti.create_user_name as createUserName, ti.create_time as createTime, tid.in_warehouse_location as inWarehouseLocation, tid.out_warehouse_location as outWarehouseLocation from transfer_info ti inner join transfer_info_detail tid on ti.id = tid.main_id and tid.is_deleted = false
${params.sqlMap.default} and ti.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ti.id desc,tid.id asc

SELECT DISTINCT ti.id, ti.code, ti.in_warehouse_name, ti.out_warehouse_name, ti.approve_status, ti.create_time FROM transfer_info ti INNER JOIN transfer_info_detail tid ON ti.id = tid.main_id AND tid.is_deleted = FALSE WHERE ti.is_deleted = FALSE AND ti.invalid_status = FALSE
and ti.approve_status in
#{item}
and ti.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > ti.bill_date
${params.permissionSql}
${item.field} ${item.sort}
ORDER BY ti.create_time desc
